# Explicacion autocontenida de lo que hace la red de conceptos. Las cifras de los ejemplos son didacticas y se calculan aqui;
# las referencias estan validadas contra Crossref (wiki_network_references).
wiki_method_explainer <- function() {
  p_ex<-stats::phyper(29,200,800,100,lower.tail=FALSE)
  p_txt<-if(p_ex<.001)"menor que 0,001" else format(round(p_ex,3),decimal.mark=",")
  tags$details(class="wiki-network-reading",tags$summary("Qu\u00e9 hace exactamente esta red, paso a paso (explicaci\u00f3n con ejemplos y referencias)"),
    tags$p("Esta red responde a una pregunta concreta: qu\u00e9 palabras tienden a aparecer en las mismas fichas (t\u00edtulos y res\u00famenes) y qu\u00e9 papel desempe\u00f1a cada una en el conjunto. Se construye en seis pasos. Las cifras de los ejemplos son inventadas con fines did\u00e1cticos; el apartado \u00abUn ejemplo con tus datos\u00bb repite el razonamiento con tu corpus."),
    tags$h4("1 / Qu\u00e9 palabras entran en la red"),
    tags$p("De cada palabra se cuenta en cu\u00e1ntas fichas aparece (frecuencia documental, DF), no cu\u00e1ntas veces se repite. Ejemplo: si \u00abturismo\u00bb se repite 30 veces en una ficha y aparece una sola vez en otras 49, su DF es 50, aunque se haya contado 79 veces. Se usa la DF porque la prueba del paso 3 compara presencia o ausencia por ficha, y porque unas pocas fichas que repiten una palabra inflar\u00edan su importancia. Por defecto entran las N palabras con mayor DF."),
    tags$p("Puede elegirse el criterio TF-IDF en su versi\u00f3n de suma: cada aparici\u00f3n se pondera por lo rara que es la palabra en el corpus (IDF; Sp\u00e4rck Jones, 1972) y se suma sobre las fichas en que aparece. Frente a la DF pura, penaliza las palabras muy generales. No se ofrece ordenar por el TF-IDF medio porque tender\u00eda a elegir casi solo palabras muy raras, que apenas coinciden entre s\u00ed y dejar\u00edan una red fragmentada, con pocas relaciones significativas y muchas palabras aisladas. Por ello el criterio recomendado y por defecto es la DF."),
    tags$p("Las palabras presentes en casi todas las fichas (por ejemplo, las de la ecuaci\u00f3n de b\u00fasqueda) se asocian con todo y aportan poca informaci\u00f3n. Luhn (1958) propuso descartar, al caracterizar un texto, tanto las palabras muy frecuentes como las muy raras. El techo de fichas permite excluir las primeras: con un techo del 30 %, se excluyen las palabras presentes en m\u00e1s del 30 % de las fichas, y la aplicaci\u00f3n declara siempre cu\u00e1les son. Por defecto no hay techo, porque depende de tu pregunta de investigaci\u00f3n y del tama\u00f1o del corpus; la lectura avisa cuando hay palabras por encima del 30 %."),
    tags$h4("2 / Cu\u00e1ndo dos palabras van juntas"),
    tags$p("Se mide con el coeficiente de Jaccard (1912): fichas con ambas palabras dividido entre fichas con al menos una. Ejemplo: si A aparece en 40 fichas, B en 30 y 20 fichas contienen las dos, hay 40 + 30 \u2212 20 = 50 fichas con alguna de ellas y Jaccard = 20 / 50 = 0,40. Vale 0 si nunca coinciden y 1 si siempre aparecen juntas. Es el m\u00e9todo cl\u00e1sico del an\u00e1lisis de co-palabras (Callon et al., 1983)."),
    tags$h4("3 / Qu\u00e9 coincidencias son m\u00e1s que azar"),
    tags$p(paste0("Dos palabras muy frecuentes coinciden a menudo solo por ser frecuentes. Ejemplo: en 1.000 fichas, A aparece en 200 y B en 100. Si se repartieran al azar, cabr\u00eda esperar 200 \u00d7 100 / 1.000 = 20 fichas con ambas. Si aparecen juntas en 30, hay 1,5 veces m\u00e1s de lo esperado (Jaccard = 30 / 270 = 0,11). La prueba hipergeom\u00e9trica calcula la probabilidad de ver 30 fichas o m\u00e1s por puro azar, manteniendo fijas las frecuencias de A y B: aqu\u00ed es ",p_txt,". Este modo de validar estad\u00edsticamente cada v\u00ednculo de una red proyectada procede de Tumminello et al. (2011).")),
    tags$p("Como se contrastan miles de pares a la vez, algunos parecer\u00edan significativos solo por casualidad. La correcci\u00f3n de Benjamini y Hochberg (1995) fija en el 5 % (por defecto) la proporci\u00f3n esperada de falsos descubrimientos entre las relaciones declaradas significativas. Las probabilidades que muestra la aplicaci\u00f3n son las ya corregidas."),
    tags$h4("4 / Qu\u00e9 relaciones se dibujan"),
    tags$p("Con cientos de relaciones significativas, el dibujo ser\u00eda una mancha ilegible. Cada palabra conserva sus k relaciones m\u00e1s intensas por Jaccard (por defecto, 3): una relaci\u00f3n se dibuja si est\u00e1 entre las k m\u00e1s intensas de alguna de sus dos palabras. Esta reducci\u00f3n solo mejora la lectura y no es una prueba estad\u00edstica: todas las l\u00edneas dibujadas son significativas, pero tambi\u00e9n lo son otras que no se dibujan. Con k = 0 se dibujan todas."),
    tags$h4("5 / Qu\u00e9 son las comunidades"),
    tags$p("El algoritmo de Louvain (Blondel et al., 2008) agrupa las palabras en comunidades, conjuntos con m\u00e1s relaciones internas de las que habr\u00eda por azar. La modularidad Q resume esa separaci\u00f3n: en redes con estructura comunitaria marcada suele estar entre 0,3 y 0,7 (Newman y Girvan, 2004). Louvain es un m\u00e9todo heur\u00edstico que puede producir comunidades poco conectadas (Traag et al., 2019); por eso se fija una semilla (2026) que hace el resultado reproducible. Las comunidades son una descripci\u00f3n exploratoria, no temas validados: contr\u00e1stalas leyendo las fichas."),
    tags$h4("6 / Qu\u00e9 papel cumple cada palabra"),
    tags$p("Se usa la tipolog\u00eda de Guimer\u00e0 y Amaral (2005) con dos medidas. La primera, z, compara las relaciones que una palabra tiene dentro de su comunidad con las del resto de su comunidad. Ejemplo: si en la comunidad el promedio es 4 relaciones internas con desviaci\u00f3n t\u00edpica 2, una palabra con 9 tiene z = (9 \u2212 4) / 2 = 2,5. Con z \u2265 2,5 es un eje (cuadrado). La segunda, la participaci\u00f3n P, mide c\u00f3mo reparte sus relaciones entre comunidades: P = 1 \u2212 suma de los cuadrados de la proporci\u00f3n de relaciones con cada comunidad. Una palabra con 10 relaciones, todas en su comunidad, tiene P = 0; con 5 en su comunidad y 5 en otra, P = 1 \u2212 (0,5\u00b2 + 0,5\u00b2) = 0,5."),
    tags$p("Una palabra que no es eje es de apoyo (c\u00edrculo) si P \u2264 0,62 y puente (tri\u00e1ngulo) si P > 0,62; una palabra que es eje se llama eje y puente (estrella) si P > 0,30. Los puentes y los ejes y puentes enlazan temas distintos. Con pocas relaciones, P es poco fiable: el listado de roles muestra las relaciones de cada palabra para valorarlo."),
    tags$h4("C\u00f3mo interpretarlo y qu\u00e9 comprobar antes de publicar"),
    tags$p("Una relaci\u00f3n indica que dos palabras tienden a aparecer en las mismas fichas; no demuestra causalidad, sinonimia ni cita. La prueba hipergeom\u00e9trica condiciona a la DF de las palabras pero no modela que unas fichas sean m\u00e1s largas que otras, algo que modelos nulos m\u00e1s flexibles contemplan (Neal, 2014). La correcci\u00f3n de Benjamini y Hochberg supone independencia o ciertas formas de dependencia positiva entre contrastes. Comunidades y roles cambian con el vocabulario elegido: repite el an\u00e1lisis variando N, el criterio, k y la resoluci\u00f3n, y presenta solo lo que se mantiene. El texto sugerido para el apartado de m\u00e9todos, con tus valores, aparece m\u00e1s abajo."),
    tags$h4("Un ejemplo con tus datos"),uiOutput("wiki_network_example"),
    tags$h4("Redacci\u00f3n sugerida para el apartado de m\u00e9todos"),uiOutput("wiki_network_methods"),
    tags$h4("Referencias"),tags$ul(lapply(wiki_network_references(),tags$li)))
}
wiki_ui <- function() tabPanel("Lectura enlazada",value="wiki",
  panel("Cuaderno de lectura / cada documento es una p\u00e1gina",
    checkboxInput("wiki_advanced_fields","Opciones avanzadas / permitir cualquier columna como texto",FALSE),
    uiOutput("wiki_text_field_control"),uiOutput("wiki_field_reading"),
    tags$details(tags$summary("Cobertura e idioma de res\u00famenes y variantes textuales"),DT::DTOutput("wiki_field_coverage")),
    selectInput("wiki_text_source","Versi\u00f3n del texto que quieres leer",c("Original de la columna elegida"="original","Texto preparado / columna usada en 02"="prepared")),
    tags$p("Cada resumen o t\u00edtulo se conserva en una ficha. Sus palabras enlazan las fichas de conceptos: desde un concepto puedes volver a todos los textos que lo mencionan. El grafo inicial muestra conceptos conectados por su presencia conjunta en las fichas. Puedes a\u00f1adir enlaces expl\u00edcitos en tus notas mediante [[concepto]] y descargar el cuaderno para Obsidian. Todo se calcula localmente, sin LLMs."),
    tags$div(class="figure-tools",actionButton("help_wiki","C\u00f3mo leer, enlazar y conservar el cuaderno",class="btn-quiet"),actionButton("code_wiki","C\u00f3digo R / solo el cuaderno",class="btn-quiet")),
    hint("C\u00f3digo R, arriba en Indicadores, muestra el c\u00f3digo de toda la secci\u00f3n. Este bot\u00f3n re\u00fane las funciones y los par\u00e1metros espec\u00edficos del cuaderno."),
    tags$div(class="row control-row",column(8,selectInput("wiki_mode","De d\u00f3nde salen los conceptos",c("Vocabulario preparado / t\u00e9rminos retenidos"="corpus","Diccionario del investigador / buscar en originales"="dictionary"))),column(4,actionButton("wiki_build","Crear \u00edndice de lectura",class="btn-primary run-analysis"))),
    conditionalPanel("input.wiki_mode === 'dictionary'",textAreaInput("wiki_dictionary","Un concepto por l\u00ednea / variantes separadas por |","salud mental | mental health\natenci\u00f3n primaria | primary care",rows=4),hint("M\u00e1ximo 100 conceptos y 300 formas. Las variantes son decisiones expl\u00edcitas del investigador. No se traduce ni se a\u00f1aden sin\u00f3nimos autom\u00e1ticamente.")),
    uiOutput("wiki_state"),tags$div(style="display:none",textOutput("wiki_ready"))),
  conditionalPanel("output.wiki_ready === 'yes'",
    panel("Grafo de conceptos / volver a los abstracts que los conectan",
      tags$p(class="wiki-orientation",tags$strong("C\u00f3mo est\u00e1 ordenado este panel. "),"El paso 1 elige y calcula la red; el paso 2 busca y resalta dentro del dibujo; despu\u00e9s vienen los ajustes del dibujo, el grafo con su ficha activa y, al final, la interpretaci\u00f3n. Solo el paso 1 recalcula la red. Todo lo dem\u00e1s cambia \u00fanicamente lo que se ve o la ficha que se lee, nunca los resultados."),
      tags$section(class="option-group wiki-step",tags$h3("1 / Qu\u00e9 red se calcula (\u00fanico paso que recalcula)"),
        selectInput("wiki_graph_view","Qu\u00e9 nodos quieres ver",c("Conceptos / vista principal"="concepts","Documentos / vista adicional"="documents","Documentos y conceptos / detalle de menciones"="bipartite")),
        conditionalPanel("input.wiki_graph_view === 'concepts'",
          tags$p("La red de conceptos ya est\u00e1 calculada con los valores por defecto: las 100 palabras presentes en m\u00e1s fichas, sus relaciones significativas y sus comunidades. Solo necesitas pulsar el bot\u00f3n si cambias alguno de los valores siguientes; si cambias alg\u00fan valor y no pulsas el bot\u00f3n, el grafo se sustituye por un aviso hasta que recalcules."),
          tags$details(tags$summary("Cambiar los valores del c\u00e1lculo (opcional)"),
            tags$p("Los colores identifican comunidades de conceptos con conexiones relativamente densas. Jaccard divide las fichas que mencionan ambos conceptos entre las fichas que mencionan al menos uno: 3 fichas conjuntas de 10 distintas = 0,30. Repetir una palabra dentro de un abstract no aumenta este peso."),
            fluidRow(column(6,selectInput("wiki_concept_criterion","C\u00f3mo se eligen las palabras",c("Fichas con la palabra (DF) / recomendado"="df","TF-IDF (suma) / penaliza las muy generales"="tfidf"))),column(6,numericInput("wiki_concept_ceiling","Techo: excluir palabras presentes en m\u00e1s de este % de fichas (100 = sin techo)",100,1,100))),
            fluidRow(column(4,numericInput("wiki_concept_top","Palabras incluidas / las N primeras seg\u00fan el criterio (0 = todas)",100,0,2000)),column(4,numericInput("wiki_concept_alpha","Asociaci\u00f3n mayor que el azar / FDR (1 = sin filtro)",.05,.001,1,step=.01)),column(4,numericInput("wiki_concept_k","Relaciones m\u00e1s fuertes por palabra (0 = todas)",3,0,50))),
            fluidRow(column(4,numericInput("wiki_concept_min_docs","Fichas con ambos conceptos / m\u00ednimo",1,1,10000)),column(4,numericInput("wiki_concept_similarity","Jaccard m\u00ednimo / conceptos",0,0,1,step=.05)),column(4,numericInput("wiki_concept_resolution","Resoluci\u00f3n Louvain / conceptos",1,.1,5,step=.1))))),
        conditionalPanel("input.wiki_graph_view !== 'concepts'",
          tags$p("La red documental adicional agrupa art\u00edculos seg\u00fan conceptos compartidos. Jaccard divide los conceptos compartidos entre los distintos presentes en ambos documentos. Esta red no se calcula sola: pulsa el bot\u00f3n para obtenerla."),
          fluidRow(column(4,numericInput("wiki_graph_shared","Conceptos compartidos entre documentos / m\u00ednimo",2,1,10000)),column(4,numericInput("wiki_similarity","Jaccard m\u00ednimo / documentos",.1,0,1,step=.05)),column(4,numericInput("wiki_resolution","Resoluci\u00f3n Louvain / documentos",1,.1,5,step=.1)))),
        tags$div(class="row control-row",column(4,actionButton("wiki_cluster","Calcular red y comunidades",class="btn-primary run-analysis")),column(8,uiOutput("wiki_cluster_state"))),
        tags$details(tags$summary("Notas t\u00e9cnicas del c\u00e1lculo y l\u00edmites"),hint("Al cambiar umbrales, vuelve a calcular. Louvain usa Jaccard, presencia/ausencia y semilla 2026. Resoluci\u00f3n 1 es un punto de partida; compara 0,5 y 1,5. Las notas no intervienen en la agrupaci\u00f3n. Los grupos son exploratorios: contr\u00e1stalos leyendo las fichas. Seleccionar una comunidad conserva la pertenencia de la red completa. Grupo 0: sin coapariciones que superen los umbrales. L\u00edmite de c\u00e1lculo: 2.000 nodos y 100.000 enlaces autom\u00e1ticos; la vista documental admite hasta 500 nodos dibujados y la de conceptos hasta 500 nodos y 5.000 coapariciones. Si se supera un l\u00edmite se explica, sin recortes ocultos."))),
      tags$section(class="option-group wiki-step",tags$h3("2 / Buscar y resaltar dentro del dibujo (no recalcula)"),
        tags$div(class="row control-row wiki-search-row",column(5,selectizeInput("wiki_find","Buscar una palabra o nodo del grafo",choices=NULL,options=predictive_options())),column(5,conditionalPanel("input.wiki_graph_view === 'concepts'",selectInput("wiki_highlight_community","Resaltar una comunidad",c("Ninguna"="none")))),column(2,actionButton("wiki_clear_highlight","Quitar resaltado",class="btn-quiet"))),
        hint("Buscar acerca la vista a esa palabra, la resalta con sus vecinas y abre su ficha a la derecha del grafo. Resaltar una comunidad deja en color sus palabras y aten\u00faa las dem\u00e1s, sin eliminarlas. Pulsar un punto resalta ese punto y sus vecinas; pulsar un espacio vac\u00edo quita el resaltado. Para dibujar solo una comunidad, en lugar de atenuar el resto, usa \u00abParte de la red que se dibuja\u00bb en los ajustes del dibujo.")),
      tags$details(class="visible-disclosure wiki-step-details",tags$summary("Ajustes del dibujo / parte de la red, nombres, movimiento y aislados (no recalculan)"),
        selectInput("wiki_graph_scope","Parte de la red que se dibuja",c("Red completa / todos los nodos calculados"="global","Entorno local de la ficha activa"="local","Solo una comunidad"="community")),
        conditionalPanel("input.wiki_graph_scope === 'community'",selectInput("wiki_community","Comunidad que se dibuja",c("Todas"="all")),hint("Se dibujan solo las palabras de esa comunidad, con la pertenencia calculada en la red completa. Grupo 0: palabras sin coapariciones que superen los umbrales.")),
        conditionalPanel("input.wiki_graph_scope === 'local'",hint("Se dibujan la ficha activa y sus vecinos directos. La ficha activa se elige en \u00abFicha activa\u00bb o pulsando un punto del grafo.")),
        conditionalPanel("input.wiki_graph_view !== 'concepts' && input.wiki_graph_scope === 'local'",fluidRow(column(6,numericInput("wiki_graph_terms","M\u00e1ximo de conceptos del documento",12,1,30)),column(6,numericInput("wiki_graph_docs","Vecinos por menciones / m\u00e1ximo",20,1,60)))),
        fluidRow(column(3,checkboxInput("wiki_graph_manual","Mostrar enlaces escritos en tus notas",TRUE)),column(3,checkboxInput("wiki_motion","Movimiento suave al arrastrar",TRUE)),column(3,conditionalPanel("input.wiki_graph_view === 'concepts'",checkboxInput("wiki_label_all","Mostrar el nombre de todas las palabras",TRUE))),column(3,checkboxInput("wiki_remove_isolates","Ocultar nodos aislados en el dibujo",TRUE)))),
      tags$details(class="visible-disclosure wiki-step-details",tags$summary("Ficha activa / elegir qu\u00e9 documento o concepto se lee a la derecha del grafo"),
        tags$div(class="row control-row wiki-search-row",column(5,selectizeInput("wiki_document","P\u00e1gina / busca t\u00edtulo, DOI o ID",choices=NULL,options=predictive_options())),column(5,selectizeInput("wiki_term","Concepto / busca su nombre",choices=NULL,options=predictive_options())),column(2,actionButton("wiki_open_term","Abrir concepto",class="btn-quiet"))),
        hint("Estos dos selectores no cambian la red ni el dibujo: solo eligen la ficha que se lee a la derecha del grafo y la que alimenta \u00abDel concepto a los documentos\u00bb. Con \u00abEntorno local de la ficha activa\u00bb, el dibujo se centra adem\u00e1s en esa ficha. Al pulsar un punto del grafo o usar el buscador, se actualizan solos. \u00abAbrir concepto\u00bb muestra la lista de menciones en una ventana.")),
      conditionalPanel("input.wiki_graph_view === 'concepts'",hint("Cada punto es una palabra; cada l\u00ednea gris, una coaparici\u00f3n significativa; el color indica la comunidad, la forma el rol y el tama\u00f1o el n\u00famero de fichas. Pulsa un punto para resaltarlo con sus vecinas y leer su ficha; pulsa una l\u00ednea para ver las fichas que la respaldan."),
        tags$details(tags$summary("C\u00f3mo leer este grafo / qu\u00e9 es cada punto, l\u00ednea, color y forma"),hint("Qu\u00e9 est\u00e1s viendo: cada punto es una palabra, no un resumen. Cada resumen es una ficha (una p\u00e1gina del cuaderno) y sus palabras enlazan con las fichas de concepto; desde una palabra se llega a todas las fichas que la mencionan (sus backlinks). Una l\u00ednea gris une dos palabras que aparecen juntas en las mismas fichas m\u00e1s de lo esperable por azar. Qu\u00e9 puedes hacer: pulsa un punto para resaltarlo con sus vecinas, ya con su nombre, y abrir su ficha de concepto junto al grafo, con la lista de fichas donde aparece; pulsa una l\u00ednea para abrir una ventana con las fichas que respaldan esa relaci\u00f3n; pulsa un espacio vac\u00edo para quitar el resaltado. La l\u00ednea discontinua con flecha es un enlace escrito en una nota. Para encontrar una palabra, usa el buscador del paso 2; para destacar una comunidad sin quitar las dem\u00e1s, el selector \u00abResaltar una comunidad\u00bb. Para ver las fichas como puntos, cambia \u00abQu\u00e9 nodos quieres ver\u00bb. Ninguna relaci\u00f3n demuestra causalidad ni una cita."),
        hint("La vista inicial muestra las 100 palabras que aparecen en m\u00e1s fichas. Una l\u00ednea une dos palabras que aparecen juntas m\u00e1s de lo esperable por azar (prueba hipergeom\u00e9trica con control de falsos descubrimientos, 5 %), y cada palabra conserva sus 3 relaciones significativas m\u00e1s fuertes por Jaccard. Color = comunidad; tama\u00f1o = fichas con la palabra; forma = rol (cuadrado = eje de su comunidad, tri\u00e1ngulo = puente entre comunidades, estrella = eje y puente, c\u00edrculo = apoyo). Todas las palabras llevan su nombre (con letra mayor los ejes, los puentes y las 15 con m\u00e1s fichas); si el dibujo se satura, desmarca \u00abMostrar el nombre de todas las palabras\u00bb, ampl\u00eda con la rueda o los botones y pasa el cursor sobre un punto para ver su ficha resumida. Cada peso Jaccard es el de la red completa de esas palabras; las comunidades se calculan solo con ellas. Para ampliar, sube N manteniendo exigentes el nivel de significaci\u00f3n o las relaciones por palabra; con 0 se incluyen todas (hasta 2.000). Usa Entorno local para explorar los vecinos de un concepto, o todos los conceptos presentes en la ficha activa. Ocultar aislados solo cambia el dibujo."))),
      conditionalPanel("input.wiki_graph_view !== 'concepts' && input.wiki_graph_scope === 'local'",hint("En Documentos, una l\u00ednea gris une dos p\u00e1ginas que comparten el m\u00ednimo elegido de conceptos. En Documentos y conceptos, los rombos muestran cada concepto y sus menciones. La l\u00ednea discontinua con flecha conserva los enlaces escritos en tus notas. Si el m\u00ednimo compartido supera los conceptos elegidos, ning\u00fan vecino puede cumplirlo; el resultado vac\u00edo es v\u00e1lido y se explica en la auditor\u00eda."),
        hint("El l\u00edmite de vecinos se aplica a menciones autom\u00e1ticas. Los enlaces de notas pueden a\u00f1adir hasta 30 p\u00e1ginas conectadas directamente; la auditor\u00eda las cuenta por separado. No se eliminan relaciones del \u00edndice completo.")),
      tags$div(class="wiki-workspace",visNetwork::visNetworkOutput("wiki_graph",height="760px"),uiOutput("wiki_reading")),
      tags$section(class="option-group wiki-step",tags$h3("3 / C\u00f3mo interpretar lo que se ve"),
        conditionalPanel("input.wiki_graph_view === 'concepts'",tags$div(class="wiki-network-reading",tags$h4("Lectura de la red para p\u00fablico no t\u00e9cnico"),uiOutput("wiki_network_reading")),wiki_method_explainer()),
        tags$details(tags$summary("Tabla de comunidades / qu\u00e9 palabras agrupa cada una"),DT::DTOutput("wiki_communities")),
        conditionalPanel("input.wiki_graph_view === 'concepts'",tags$details(tags$summary("Roles de las palabras / ejes, puentes y apoyos"),hint("Eje: muchas m\u00e1s relaciones dentro de su comunidad que el resto de ella (z \u2265 2,5). Puente: reparte sus relaciones entre comunidades (participaci\u00f3n P alta). Apoyo: se relaciona sobre todo con su propia comunidad. Criterios de Guimer\u00e0 y Amaral (2005); son descriptivos."),DT::DTOutput("wiki_roles"))),
